#include "UiModel.h"
#include "StreamAssembler.h"
#include <cassert>
struct FakeDisplay:DisplayAdapter{String output;void clear(uint16_t)override{output.clear();}void text(int,int,const String&s,uint16_t)override{output+=s;output+=' ';}void button(int,int,int,int,const String&s)override{output+=s;output+=' ';}};
int main(){UiModel ui;ui.setEvents({{"old","1.1.1.1","TEXT",2,100,false,false},{"new","2.2.2.2","ESC",3,200,true,false}});assert(ui.recent[0].id=="new");FakeDisplay d;ui.draw(d,"wifi","192.0.2.1","CONNECTED","LISTENING",2);assert(d.output.find("2.2.2.2")<d.output.find("1.1.1.1"));assert(d.output.find("RECEIVED INCOMPLETE")!=String::npos);uint8_t bytes[]={0,27,255};StreamAssembler stream(32768);assert(stream.append(bytes,3));ui.onTouch(20,110);assert(ui.page==UiPage::RawHex&&ui.selectedId=="new");ui.setRaw(stream.bytes());ui.draw(d,"","","","",0);assert(d.output.find("00 1b ff")!=String::npos);ui.onTouch(170,40);ui.draw(d,"","","","",0);assert(d.output.find("...")!=String::npos);assert(ui.selectedRaw==stream.bytes());ui.onTouch(20,40);ui.onTouch(200,10);assert(ui.page==UiPage::WiFiSettings);ui.onTouch(8,143);assert(ui.wifiSsid=="A");ui.onTouch(140,110);assert(ui.connectRequested);}
